package com.brainserve.onboarding.notifications.api.controller;
import com.brainserve.onboarding.common.api.ApiResponse;import com.brainserve.onboarding.common.observability.RequestContext;import com.brainserve.onboarding.common.security.TenantPrincipal;import com.brainserve.onboarding.notifications.api.request.*;import com.brainserve.onboarding.notifications.api.response.NotificationTemplateResponse;import com.brainserve.onboarding.notifications.application.service.NotificationTemplateService;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.util.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/notification-templates") @PreAuthorize("hasAuthority('NOTIFICATION_MANAGE')") public class NotificationTemplateController {private final NotificationTemplateService service;public NotificationTemplateController(NotificationTemplateService service){this.service=service;}@PostMapping ApiResponse<NotificationTemplateResponse> create(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody CreateNotificationTemplateRequest r,HttpServletRequest req){return ApiResponse.success(service.create(p,r,req),RequestContext.requestId());}@GetMapping ApiResponse<List<NotificationTemplateResponse>> list(@AuthenticationPrincipal TenantPrincipal p,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){var r=service.list(p,page,size);return ApiResponse.success(r.items(),Map.of("page",r.page(),"size",r.size(),"totalElements",r.totalElements(),"totalPages",r.totalPages()),RequestContext.requestId());}@GetMapping("/{id}")ApiResponse<NotificationTemplateResponse> get(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID id){return ApiResponse.success(service.get(p,id),RequestContext.requestId());}@PutMapping("/{id}")ApiResponse<NotificationTemplateResponse> update(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID id,@Valid @RequestBody SaveNotificationTemplateRequest r,HttpServletRequest req){return ApiResponse.success(service.update(p,id,r,req),RequestContext.requestId());}@PostMapping("/{id}/archive")ApiResponse<NotificationTemplateResponse> archive(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID id,@Valid @RequestBody ResourceVersionRequest r,HttpServletRequest req){return ApiResponse.success(service.archive(p,id,r.version(),req),RequestContext.requestId());}}
